from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.cell_block.classical_cell_block.cell_block_prototype import CellBlock


class CellBlockFactory(OperationFactoryPrototype):
    def __init__(self):
        super(CellBlockFactory, self).__init__()
        self.cell_block_instance = None

    def get_kpi(self, cell_dist_name=""):
        """
        Gets kpi for cell block operation.
        :param cell_dist_name: dist_name of the cell, which KPI cell block timeout will be applied to
        :type cell_dist_name: str
        :return: dictionary with timeout, requirement and operation description for cell block
        :rtype: dict
        """
        self.cell_block_instance = CellBlock(self.bts)

        return self.cell_block_instance.get_kpi(cell_dist_name=cell_dist_name)
